static inline uint16_t byte_swap16(uint16_t v)
{
	return (uint16_t)(((v << 8) & 0xff00) | ((v >> 8) & 0x00ff));
}
static inline uint32_t byte_swap32(uint32_t v)
{
	uint16_t lo = (uint16_t)(v & 0xffff);
	uint16_t hi = (uint16_t)(v >> 16);
	return ((uint32_t)byte_swap16(lo) << 16) | byte_swap16(hi);
}
static inline uint32_t byte_swap16_in32(uint32_t v)
{
	uint16_t t = (uint16_t)(v & 0xffff);
	return (uint32_t)byte_swap16(t);
}
static inline uint32_t flash_initialize_tail(uint32_t addr, uint32_t value)
{
	return APICAL_WRITE_32(addr, value);
}
