uint32_t isp_modify_dma_direction_isra_0(void *arg1)
{
	struct isp_dma_ctx {
		uint32_t _r0[3];
		uint32_t magic;
		uint32_t _r4[13];
		uint32_t base;
		uint32_t dir;
		uint32_t *cfg;
		uint32_t _r7[27];
		uint32_t value;
		uint8_t *cur;
		uint8_t count;
		uint32_t _r10[11];
	} *ctx = (struct isp_dma_ctx *)arg1;

	uint32_t ret;

	if (ctx->dir != 4)
		return 4;

	ret = ctx->cfg[5] & 0x20;
	if (ret)
		return ret;

	{
		uint32_t v = APICAL_READ_32((ctx->base << 8) + 0xb24);
		uint32_t idx = ((v >> 8) & 7) + 1;
		uint32_t q = idx % ctx->count;
		uint8_t *b = ctx->value + q + 0x7d;
		uint8_t *cur = ctx->cur;

		if (cur == b)
			return b;

		ctx->cur = b;

		if (ctx->magic == 0x3132564e || ctx->magic == 0x3231564e)
			APICAL_WRITE_32((ctx->base << 8) + 0xba0, ctx->value);

		return APICAL_WRITE_32((ctx->base << 8) + 0xb20, ctx->value);
	}
}

static void tx_isp_t30_ispcore_enable_lfb_channel(
	struct tx_isp_t30_core_output_channel *chan)
{
	u32 base;

	if (!chan || chan->state != TX_ISP_T30_MODULE_RUNNING ||
	    !chan->pad || !(chan->pad->link.flag & BIT(5)) || chan->dma_state)
		return;

	base = 0xb00 + chan->index * 0x100;
	switch (chan->fmt.pix.pixelformat) {
	case V4L2_PIX_FMT_NV12:
	case V4L2_PIX_FMT_NV21:
		/* UV writer, followed by the Y writer through OEM fall-through. */
		APICAL_WRITE_32(base + 0xa4, 0x02);
		APICAL_WRITE_32(base + 0x24, 0x02);
		chan->dma_state = 1;
		break;
	default:
		APICAL_WRITE_32(base + 0x24, 0x02);
		chan->dma_state = 1;
		break;
	}
}

/*
 * 1 while the firmware instance (event queue, FSM state) is initialised.  The
 * OEM driver reaches the same guarantee by keeping the ISP interrupt masked
 * until apical_fw_init() has finished; this driver's IRQ line can fire inside
 * that window (frame IRQ between the handler table and the event-queue setup:
 * apical_loop_buffer_write_u8 on a NULL buffer, fatal exception in interrupt,
 * Lu-Fi/openimp#176).  Events that arrive before the init completes are
 * acknowledged by the caller and dropped here.
 */
static int tx_isp_t30_fw_ready;

static void tx_isp_t30_dispatch_firmware_irqs(u32 status)
{
	const u32 recovered_sources = BIT(0) | BIT(3) | BIT(4);
	unsigned int source;

	if (!ACCESS_ONCE(tx_isp_t30_fw_ready))
		return;

	/*
	 * APICAL interrupt status bits are the firmware source indices installed
	 * through system_set_interrupt_handler().  The OEM module dispatches every
	 * asserted source, but several recovered callbacks are not yet safe enough
	 * to do that.  Source 7 enters the incomplete CMOS history state machine
	 * and corrupts the live pipeline.  Keep frame end (0), AE (3), and AWB (4):
	 * source 0 is required for event 0xb and per-frame tuning/NR updates.
	 */
	if (tx_isp_t30_fw_dispatch_trace_count++ < 8)
		pr_err("tx-isp-t30: APICAL dispatch status=%04x fe=%p ae=%p awb=%p ctx=%p\n",
		       status, isr_func[0], isr_func[3], isr_func[4],
		       isr_param[0]);
	status &= recovered_sources;
	for (source = 0; source < ARRAY_SIZE(isr_func); source++) {
		if ((status & BIT(source)) && isr_func[source]) {
			u64 ls_start = tx_ls_work_begin();

			isr_func[source](isr_param[source]);
			tx_ls_work_end(source, ls_start);
		}
	}
}

static int tx_isp_t30_ispcore_interrupt(struct tx_isp_t30_subdev *sd)
{
	struct tx_isp_t30_core_video_view *core;
	u32 irq_status;
	u32 clear;
	int ret = IRQ_HANDLED;

	if (!sd || IS_ERR(sd))
		return IRQ_HANDLED;
	core = sd->dev_priv;
	if (!core || IS_ERR(core))
		return IRQ_HANDLED;

	irq_status = APICAL_READ_32(0xa0) & 0xffff;
	tx_ls_isr(&irq_status, 1);
	if (tx_isp_t30_irq_entry_trace_count++ < 8)
		pr_err("tx-isp-t30: ISP IRQ entry sd=%p status=%04x ack=%08x\n",
		       sd, irq_status, APICAL_READ_32(0xa4));
	if (!irq_status) {
		/*
		 * The event-clear register is edge operated.  Core stream-on clears
		 * all stale events with a 0 -> 0xffff transition, but the clear
		 * inputs must then be returned to zero before a new event can latch.
		 * The OEM ISR normally does that as part of acknowledging its first
		 * pending event.  Arm it explicitly when the first IRQ races the
		 * status latch, otherwise every subsequent event is suppressed.
		 */
		clear = APICAL_READ_32(0xa4) & 0xffff0000;
		if (APICAL_READ_32(0xa4) & 0xffff)
			APICAL_WRITE_32(0xa4, clear);
		return IRQ_HANDLED;
	}
	clear = APICAL_READ_32(0xa4) & 0xffff0000;
	APICAL_WRITE_32(0xa4, clear);
	APICAL_WRITE_32(0xa4, clear | irq_status);
	if (tx_isp_t30_irq_trace_count++ < 8)
		pr_err("tx-isp-t30: ISP irq=%04x frame=%u sequence=%u\n",
		       irq_status, core->frame_state, core->frame_sequence);

	if (irq_status & BIT(7)) {
		core->frame_state = 1;
		core->frame_sequence++;
		ret = IRQ_WAKE_THREAD;
	}
	if (irq_status & BIT(0)) {
		u32 bayer = APICAL_READ_32(0x18) & 3;

		core->frame_state = 0;
		/*
		 * OEM frame-end case: mirror changes requested by s_ctrl take effect
		 * here.  0x40 bit 1 is set for the unmirrored picture; a horizontal
		 * mirror also moves the bayer phase by one column, a vertical sensor
		 * flip by one row when the input format changed.
		 */
		if (core->hflip_change == 1) {
			core->hflip_change = 0;
			APICAL_WRITE_32(0x40, (APICAL_READ_32(0x40) & ~2U) |
					((core->hflip_state == 0) << 1));
			bayer ^= 1;
		}
		if (core->vflip_change == 1) {
			if (core->vin.mbus_change == 1)
				bayer ^= 2;
			core->vflip_change = 0;
		}
		APICAL_WRITE_32(0x18, (APICAL_READ_32(0x18) & ~3U) | bayer);
		/*
		 * OEM enables the FR writer from the first frame-end interrupt.
		 * Omitting this leaves both writers at zero and starves LFB/NCU.
		 */
		if (core->channels && core->num_channels)
			tx_isp_t30_ispcore_enable_lfb_channel(&core->channels[0]);
		if (g_switch_lfb_off) {
			isp_lfb_ctrl_flb_enable(0);
			g_switch_lfb_off = 0;
		}
		if (g_switch_lfb_on) {
			isp_lfb_ctrl_flb_enable(1);
			g_switch_lfb_on = 0;
		}
		/*
		 * OEM ispcore_interrupt_service_routine, frame end: tuning event
		 * 0x4000002 (frame done) through the handler the tuning block holds at
		 * +0x40d4; WaitFrame and the frame-done count depend on it.
		 */
		{
			struct tx_isp_t30_core_tuning_view *tcore = (void *)core;

			if (tcore->tuning && !IS_ERR(tcore->tuning))
				isp_core_tuning_event((int32_t *)tcore->tuning, 0x4000002, 0);
		}
		/*
		 * OEM frame-end case: a day/night change requested through
		 * DAY_OR_NIGHT (0x80000e1) becomes tuning event 0x4000003, which
		 * reloads the day or night tables and sets the UV clip (512 at
		 * night = monochrome).  Without it the request only set the flag.
		 */
		if (core->daynight_switch == 1) {
			struct tx_isp_t30_core_tuning_view *tcore = (void *)core;

			if (tcore->tuning && !IS_ERR(tcore->tuning))
				isp_core_tuning_event((int32_t *)tcore->tuning,
						      0x4000003, 0);
			core->daynight_switch = 0;
		}
	}
	tx_isp_t30_dispatch_firmware_irqs(irq_status);
	if (simple_3a && (irq_status & BIT(3)))
		ret = IRQ_WAKE_THREAD;

	return ret;
}

