				return -EINVAL;
			offset = tx_isp_t30_sequence_u16(data + 1);
			data += 3;
			continue;
		case 0x02:
			if (end - data < 5)
				return -EINVAL;
			offset = tx_isp_t30_sequence_u32(data + 1);
			data += 5;
			continue;
