static int tx_isp_t30_tuning_set_antiflicker(int mode)
{
	static const u8 frequency_hz[] = { 0, 50, 60 };

	if ((u32)mode >= ARRAY_SIZE(frequency_hz))
		return -EINVAL;
	/* OEM control values are off/50 Hz/60 Hz; APICAL stores frequency. */
	stab[52] = frequency_hz[mode];
	pr_info("tx-isp-t30: anti-flicker mode=%d frequency=%uHz\n",
		mode, frequency_hz[mode]);
	return 0;
}

static void tx_isp_t30_ae_apply_antiflicker(
	const struct tx_isp_t30_core_sensor_view *core,
	const struct tx_isp_t30_sensor_attribute_view *attr,
	s32 total_exposure_log2, u32 min_integration, u32 max_integration,
	s32 max_isp_digital_gain_log2, u32 *integration_time,
	s32 *analog_gain_log2, s32 *isp_digital_gain_log2)
{
	u32 fps_numerator = core->fps >> 16;
	u32 fps_denominator = core->fps & 0xffff;
	u32 frequency = stab[52];
	u32 denominator;
	u32 quantized;
	u32 step_lines;
	u64 line_rate;
	s32 gain_log2;

	if ((frequency != 50 && frequency != 60) ||
	    !fps_numerator || !fps_denominator || !attr->total_height)
		return;

	/*
	 * APICAL CMOS formula: frame rate * frame height divided by twice the
	 * mains frequency.  Timing comes exclusively from the live sensor ABI.
	 */
	line_rate = (u64)fps_numerator * attr->total_height;
	denominator = fps_denominator * frequency * 2;
	step_lines = div64_u64(line_rate, denominator);
	if (!step_lines ||
	    tx_isp_flicker_integration_floor(*integration_time, step_lines,
					      min_integration,
					      max_integration,
					      &quantized))
		return;
	if (quantized == *integration_time)
		return;

	*integration_time = quantized;
	gain_log2 = max_t(s32, 0, total_exposure_log2 -
		log2_fixed_to_fixed(quantized, 0, 16));
	*analog_gain_log2 = min_t(s32, gain_log2, attr->max_again);
	*isp_digital_gain_log2 = clamp_t(s32,
		gain_log2 - *analog_gain_log2, 0,
		max_isp_digital_gain_log2);
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000038ee0 origin=model_output original=init_module */
int32_t init_module(void)
{
	int32_t ret;
	int32_t r;

	tx_isp_root_driver = kzalloc(sizeof(*tx_isp_root_driver), GFP_KERNEL);
	if (!tx_isp_root_driver)
		return -ENOMEM;
	tx_isp_root_driver->guard_before = TX_ISP_T30_ROOT_DRIVER_GUARD;
	tx_isp_root_driver->guard_after = TX_ISP_T30_ROOT_DRIVER_GUARD;

	regtrace_patch_relocated_data();

	r = private_driver_get_interface();
	if (r != 0) {
		ret = r;
		printk("Failed to insmod isp driver!\n");
		goto failed_root_driver;
	}

	r = private_platform_device_register(&tx_isp_platform_device);
	if (r != 0) {
		ret = r;
		printk("Failed to insmod isp driver!!!\n");
		goto failed_root_driver;
	}

	r = private_platform_driver_register(&tx_isp_root_driver->driver);
	if (r != 0) {
		ret = r;
		private_platform_device_unregister(&tx_isp_platform_device);
		goto failed_root_driver;
	}
	tx_isp_root_driver->registered_private =
		tx_isp_root_driver->driver.driver.p;
	tx_isp_root_driver->registered = true;

	r = tx_isp_sinfo_init();
	if (r != 0) {
		tx_isp_t30_root_driver_unregister();
		private_platform_device_unregister(&tx_isp_platform_device);
		return r;
	}
	register_module_notifier(&tx_isp_t30_sensor_module_nb);
	r = tx_isp_t30_v4l2_init();
	if (r != 0) {
		unregister_module_notifier(&tx_isp_t30_sensor_module_nb);
		tx_isp_sinfo_exit();
		tx_isp_t30_root_driver_unregister();
		private_platform_device_unregister(&tx_isp_platform_device);
		return r;
	}
	return 0;

failed_root_driver:
	tx_isp_t30_root_driver_unregister();
	return ret;
}

